	for _, snap := range snapshots {
		// Bonus for high cache hit rate (rewards warm caches)
		scores[snap.ID] += snap.CacheHitRate * 0.35 * prefixBoost

		// Bonus for available memory (can accept large requests)
		if maxFreeKV > 0 {
